import type { UnitQuestion, UnitTemplate } from "./unit-seeds.js";

type Role = "oliver" | "ruby" | "marcus";
type Pair = string;
type Choice = readonly [prompt: string, answer: string, wrongA: string, wrongB: string, explanation: string];
type Fill = readonly [prompt: string, answer: string, explanation: string];
type Row = readonly [role: Role, title: string, opening: Pair, clue: Pair, development: Pair,
  choice: Choice, action: string, actionExplanation: string, fill: Fill];
type Source = Readonly<{ volumeId: string; unitNumber: number; evidenceUrl: string;
  designFocus: string; evidenceLevel: NonNullable<UnitTemplate["learningReference"]>["evidenceLevel"] }>;

function pair(value: Pair): { english: string; chinese: string } {
  const index = value.indexOf("|");
  if (index < 1 || index === value.length - 1) throw new Error("单元剧情缺少中英对应文本");
  return { english: value.slice(0, index).trim(), chinese: value.slice(index + 1).trim() };
}

function orderOptions(answer: string): string[] {
  const tokens = answer.match(/[\p{L}\p{N}']+|[.!?]/gu) ?? [];
  if (tokens.length < 3 || tokens.length > 12) throw new Error(`排序题词块数量无效：${answer}`);
  return tokens.reverse();
}

