function makeUnit(grade: number, slot: number, objective: string, row: Row, source: Source): UnitTemplate {
  const [role, title, opening, clue, development, choice, action, actionExplanation, fill] = row;
  const [prompt, answer, wrongA, wrongB, explanation] = choice;
  const [fillPrompt, fillAnswer, fillExplanation] = fill;
  const questions: UnitQuestion[] = [
    { id: "q1", kind: "choice", prompt, options: [wrongA, answer, wrongB], answer, explanation },
    { id: "q2", kind: "order", prompt: "排出回应当前任务的英文句子", options: orderOptions(action), answer: action, explanation: actionExplanation },
    { id: "q3", kind: "write", prompt: fillPrompt, options: [], answer: fillAnswer, explanation: fillExplanation },
  ];
  return { id: `unit-v2-${role}-g${String(grade)}-${String(slot)}`, roleKey: role, grade, title, objective,
    learningReference: source,
    scene: [
      { speaker: "narrator", ...pair(opening) },
      { speaker: "character", ...pair(clue) },
      { speaker: "narrator", ...pair(development) },
    ], questions };
}

