export const expandedUnitSeedsV2: readonly UnitTemplate[] = missions.flatMap(mission => {
  const sources = sourceByGrade[mission.grade];
  if (!sources) throw new Error(`缺少 ${String(mission.grade)} 年级的教材参考`);
  const firstExtraSlot = [3, 7, 8, 9, 10].includes(mission.grade) ? 2 : 1;
  const source = sources[(mission.slot - firstExtraSlot) % sources.length];
  if (!source) throw new Error("缺少单元来源记录");
  return mission.rows.map(row => makeUnit(mission.grade, mission.slot, mission.objective, row, source));
});
